  "inlineSchema": "generator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\nmodel Doctor {\n  id                    String   @id @default(uuid())\n  doctorName            String\n  phone                 String\n  bmdcRegNumber         String   @unique\n  specialtyAndInstitute String\n  chamber               String\n  territoryAndMio       String\n  email                 String?\n  tier                  String\n  patientVolumeDaily    Int      @default(30)\n  createdAt             DateTime @default(now())\n  updatedAt             DateTime @updatedAt\n}\n\nenum StaffStatus {\n  ACTIVE\n  INACTIVE\n  SUSPENDED\n  TERMINATED\n  PROBATION\n  ON_LEAVE\n}\n\nenum PaymentStatus {\n  PENDING\n  PAID\n  PROCESSING\n}\n\nmodel Role {\n  id          String   @id @default(uuid())\n  name        String   @unique\n  permissions String[]\n  staff       Staff[]\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n}\n\nmodel Staff {\n  id          String      @id @default(uuid())\n  empId       String      @unique\n  fullName    String\n  phone       String\n  email       String?\n  nidNumber   String?\n  fathersName String?\n  mothersName String?\n  address     String?\n  department  String?\n  territory   String?\n  supervisor  String? // <--- Added supervisor field\n  status      StaffStatus @default(ACTIVE)\n  joiningDate DateTime    @default(now())\n  createdAt   DateTime    @default(now())\n  updatedAt   DateTime    @updatedAt\n\n  roleId   String?\n  role     Role?    @relation(fields: [roleId], references: [id])\n  salaries Salary[]\n}\n\nmodel Salary {\n  id               String        @id @default(uuid())\n  staffId          String\n  staff            Staff         @relation(fields: [staffId], references: [id], onDelete: Cascade)\n  payPeriod        String        @default(\"September 2026\")\n  baseSalary       Decimal       @db.Decimal(10, 2)\n  houseRent        Decimal       @default(0.00) @db.Decimal(10, 2)\n  medicalAllowance Decimal       @default(0.00) @db.Decimal(10, 2)\n  conveyanceTaDa   Decimal       @default(0.00) @db.Decimal(10, 2)\n  salesIncentive   Decimal       @default(0.00) @db.Decimal(10, 2)\n  specialBonus     Decimal       @default(0.00) @db.Decimal(10, 2)\n  providentFund    Decimal       @default(0.00) @db.Decimal(10, 2)\n  taxDeduction     Decimal       @default(0.00) @db.Decimal(10, 2)\n  otherDeductions  Decimal       @default(0.00) @db.Decimal(10, 2)\n  leaveDays        Int           @default(0) // <--- Track days off / leave here\n  netPay           Decimal       @db.Decimal(10, 2)\n  paymentStatus    PaymentStatus @default(PENDING)\n  effectiveDate    DateTime\n  createdAt        DateTime      @default(now())\n  updatedAt        DateTime      @updatedAt\n\n  @@unique([staffId, payPeriod])\n}\n\nmodel Client {\n  id                    String   @id @default(uuid())\n  clientCode            String   @unique\n  pharmacyName          String\n  proprietor            String?\n  phone                 String\n  drugLicenseNo         String?\n  tradeLicenseNo        String?\n  address               String?\n  territory             String?\n  assignedMio           String?\n  creditLimitBDT        Decimal  @default(150000) @db.Decimal(12, 2)\n  outstandingBalanceBDT Decimal  @default(0.00) @db.Decimal(12, 2)\n  creditTermDays        Int      @default(30)\n  status                String   @default(\"Active / Healthy\")\n  lastBilledDate        String?\n  createdAt             DateTime @default(now())\n  updatedAt             DateTime @updatedAt\n}\n\nmodel Order {\n  id             String   @id @default(uuid())\n  orderNumber    String   @unique\n  orderDate      String\n  pharmacyName   String\n  territory      String\n  assignedMio    String\n  itemsSummary   String\n  itemsDetail    Json? // <-- Stores the exact array of items [{ no, description, quantity, unitCost, total }]\n  totalBoxes     Int\n  orderValue     Decimal  @db.Decimal(12, 2)\n  discount       Decimal  @default(0.00) @db.Decimal(12, 2)\n  comments       String?\n  deliveryMethod String\n  status         String\n  challanNumber  String?\n  invoiceNumber  String?\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n}\n\nmodel TreasuryDeposit {\n  id              String   @id @default(uuid())\n  destinationType String // \"Cash Drawer\" or \"Bank Account\"\n  destinationName String // e.g. \"Head Office Cash Safe\" or \"Eastern Bank PLC\"\n  amount          Decimal  @db.Decimal(12, 2)\n  salesRep        String?\n  discrepancy     Decimal  @default(0.00) @db.Decimal(12, 2)\n  resolution      String?\n  createdAt       DateTime @default(now())\n}\n\nmodel ExpenseVoucher {\n  id            String   @id @default(uuid())\n  voucherNo     String   @unique\n  payeeName     String\n  category      String\n  fundingSource String // \"Cash Safe\" or \"Bank Account\"\n  sourceDetail  String // e.g. \"Head Office Cash Safe\" or \"Eastern Bank PLC\"\n  amount        Decimal  @db.Decimal(12, 2)\n  paymentDate   String\n  notes         String?\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n}\n\nenum AccountCategory {\n  BANK\n  CASH\n}\n\nenum JournalFlowType {\n  INFLOW // Deposits, Capital, Sales Collection\n  OUTFLOW // Withdrawals, Expense Payments\n  TRANSFER // Cash-to-Bank, Bank-to-Cash, Bank-to-Bank\n  LOAN // Bank Loans, Director/Investor Borrowings\n}\n\nmodel FinancialAccount {\n  id            String          @id @default(uuid())\n  accountTitle  String          @unique\n  category      AccountCategory // BANK or CASH\n  institution   String // e.g., \"Eastern Bank PLC\" or \"Main Cash Drawer\"\n  accountNumber String // Account # or \"CASH-HQ-01\"\n  branch        String // e.g., \"Gulshan Corporate\" or \"Mirpur HQ\"\n  accountClass  String // \"Current\", \"Savings\", \"Petty Cash\", \"Escrow\", \"Cash Counter\"\n  balance       Decimal         @default(0.00) @db.Decimal(14, 2)\n  isActive      Boolean         @default(true)\n  createdAt     DateTime        @default(now())\n  updatedAt     DateTime        @updatedAt\n\n  debitEntries  JournalTransaction[] @relation(\"SourceAccount\")\n  creditEntries JournalTransaction[] @relation(\"DestinationAccount\")\n}\n\nmodel JournalTransaction {\n  id                   String          @id @default(uuid())\n  entryDate            String\n  refCode              String          @unique\n  flowType             JournalFlowType\n  particulars          String\n  fundingEntity        String? // e.g., \"Loan from DBBL\", \"Director Equity\", \"Chemist Cash\"\n  method               String // \"Cash Handover\", \"BEFTN / RTGS\", \"Cheque Deposit\", \"ATM\"\n  amount               Decimal         @db.Decimal(14, 2)\n  reconciliationStatus String          @default(\"Reconciled\")\n\n  sourceAccountId String?\n  sourceAccount   FinancialAccount? @relation(\"SourceAccount\", fields: [sourceAccountId], references: [id], onDelete: SetNull)\n\n  destinationAccountId String?\n  destinationAccount   FinancialAccount? @relation(\"DestinationAccount\", fields: [destinationAccountId], references: [id], onDelete: SetNull)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n",
